using System;using System.Runtime.InteropServices;using System.Threading.Tasks;using System.Windows.Forms;
class MeditationBridgeTest:Form {
 [DllImport("kernel32.dll")]static extern IntPtr VirtualAlloc(IntPtr a,UIntPtr n,uint t,uint p);[DllImport("kernel32.dll")]static extern bool VirtualProtect(IntPtr a,UIntPtr n,uint p,out uint old);[DllImport("kernel32.dll")]static extern bool VirtualFree(IntPtr a,UIntPtr n,uint t);[DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr w,uint m,IntPtr a,IntPtr b);static int exit=1;
 protected override void WndProc(ref Message m){if(m.Msg==0x8001){m.Result=new IntPtr(42);return;}base.WndProc(ref m);}MeditationBridgeTest(){Shown+=async(s,e)=>{var w=Handle;await Task.Run(()=>Run(w));Close();};}
 static void Run(IntPtr w){var code=VirtualAlloc(IntPtr.Zero,new UIntPtr(4096),0x3000,4);var state=Marshal.AllocHGlobal(16);try{for(int i=0;i<16;i++)Marshal.WriteByte(state,i,0);byte[] stub={0x8B,0x44,0x24,4,0x0F,0xB7,0,0x89,1,0x8B,0x44,0x24,8,0x89,0x41,4,0xFF,0x41,8,0xB8,1,0,0,0,0xC2,8,0};Marshal.Copy(stub,0,code,stub.Length);uint old;VirtualProtect(code,new UIntPtr(4096),0x20,out old);MeditationBridge b;using(b=new MeditationBridge(w,MeditationBridge.Addr(state),MeditationBridge.Addr(code))){b.SetSitting(true);if(Marshal.ReadInt32(state)!=0x2E||Marshal.ReadInt32(state,4)!=2)throw new Exception("Sentar incorreto");Console.WriteLine("PASS comando meditar 2E00 com dois bytes");b.SetSitting(false);if(Marshal.ReadInt32(state)!=0x2F||Marshal.ReadInt32(state,8)!=2)throw new Exception("Levantar incorreto");Console.WriteLine("PASS comando levantar 2F00 sem repeticao extra");if(b.ExecutedThread!=b.UiThread||b.LastSendResult!=1)throw new Exception("Thread ou retorno incorreto");Console.WriteLine("PASS execucao na thread da janela e retorno aceito");}if(!b.RestoreSucceeded||SendMessage(w,0x8001,IntPtr.Zero,IntPtr.Zero).ToInt32()!=42)throw new Exception("Restauracao falhou");Console.WriteLine("PASS ponte removida e janela restaurada");exit=0;}catch(Exception e){Console.WriteLine(e);}finally{VirtualFree(code,UIntPtr.Zero,0x8000);Marshal.FreeHGlobal(state);}}
